<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class ProductVariant extends Model {protected $guarded=[]; protected $casts=['price'=>'decimal:2','stock'=>'integer','is_active'=>'boolean']; public function product(){return $this->belongsTo(Product::class);} public function inventoryMovements(){return $this->hasMany(InventoryMovement::class,'product_variant_id');} }
